import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.setStatus(401);
            resp.getWriter().write("{\"error\":\"unauthorized\"}");
            return;
        }

        String body = req.getReader().lines().reduce("", String::concat);
        JSONObject params = new JSONObject(body);
        String reportType = params.optString("report_type", "summary");
        String dateRange = params.optString("date_range", "last_30d");
        String customFilter = params.optString("filter", "");
        String sortCol = params.optString("sort_by", "created_at");
        String sortDir = params.optString("sort_dir", "DESC");

        // Validate sort direction
        if (!sortDir.equalsIgnoreCase("ASC") && !sortDir.equalsIgnoreCase("DESC")) {
            sortDir = "DESC";
        }

        // Build report query
        String baseQuery = getBaseQuery(reportType);
        String dateClause = buildDateClause(dateRange);
        String filterClause = "";
        if (!customFilter.isEmpty()) {
            // Apply user-specified filter condition
            filterClause = " AND category = '" + customFilter + "'";
        }

        String orderClause = " ORDER BY " + sanitizeColumnName(sortCol) + " " + sortDir;
        String fullQuery = baseQuery + dateClause + filterClause + orderClause + " LIMIT 500";

        log.info("Executing report query for type: " + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(fullQuery)) {

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query_failed\"}");
        }
    }

    private String getBaseQuery(String reportType) {
        switch (reportType) {
            case "detailed": return "SELECT id, title, category, amount, created_at, status FROM transactions WHERE 1=1";
            case "users": return "SELECT id, username, email, role, last_login FROM users WHERE 1=1";
            default: return "SELECT category, COUNT(*) as cnt, SUM(amount) as total FROM transactions WHERE 1=1";
        }
    }

    private String buildDateClause(String range) {
        switch (range) {
            case "last_7d": return " AND created_at > NOW() - INTERVAL '7 days'";
            case "last_90d": return " AND created_at > NOW() - INTERVAL '90 days'";
            default: return " AND created_at > NOW() - INTERVAL '30 days'";
        }
    }

    private String sanitizeColumnName(String col) {
        // Allow only alphanumeric and underscore
        return col.replaceAll("[^a-zA-Z0-9_]", "");
    }

    private boolean validateSession(String token) {
        // Validates against session store
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT 1 FROM sessions WHERE token = ? AND expires_at > NOW()")) {
            ps.setString(1, token);
            return ps.executeQuery().next();
        } catch (SQLException e) {
            return false;
        }
    }
}
